Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000009;
typedef pair<int,int> pii;
typedef pair<pii,int> ppi;

vector<int> headEdge, toNode, nextEdge, edgeCap;
vector<int> distLevel, current;
int src, sink;

void addEdge(int u, int v, int c) {
    int id = (int)toNode.size();
    toNode.push_back(v);
    edgeCap.push_back(c);
    nextEdge.push_back(headEdge[u]);
    headEdge[u] = id;

    toNode.push_back(u);
    edgeCap.push_back(0);
    nextEdge.push_back(headEdge[v]);
    headEdge[v] = id + 1;
}

bool bfs() {
    fill(distLevel.begin(), distLevel.end(), -1);
    queue<int> q;
    q.push(src);
    distLevel[src] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int e = headEdge[u]; e != -1; e = nextEdge[e]) {
            int v = toNode[e];
            if (distLevel[v] == -1 && edgeCap[e] > 0) {
                distLevel[v] = distLevel[u] + 1;
                q.push(v);
                if (v == sink) return true;
            }
        }
    }
    return false;
}

long long dfs(int u, int f) {
    if (f == 0) return 0;
    if (u == sink) return f;
    for (int &e = current[u]; e != -1; e = nextEdge[e]) {
        int v = toNode[e];
        if (distLevel[v] != distLevel[u] + 1 || edgeCap[e] == 0) continue;
        long long pushed = dfs(v, min(f, edgeCap[e]));
        if (pushed) {
            edgeCap[e] -= (int)pushed;
            edgeCap[e ^ 1] += (int)pushed;
            return pushed;
        }
    }
    return 0;
}

long long maxflow() {
    long long ans = 0;
    while (bfs()) {
        current = headEdge;
        while (long long pushed = dfs(src, INF)) ans += pushed;
    }
    return ans;
}

int n, m, deadline;
char sci[101][101], rea[101][101];
int danger[101][101];

bool valid(int r, int c) { return r >= 0 && c >= 0 && r < n && c < m; }
int idCell(int x, int y) { return 1 + m * x + y; }

int main() {
    ios::sync_with_stdio(false);
    cin >> n >> deadline;
    ++deadline;
    m = n;

    for (int i = 0; i < n; ++i) cin >> sci[i];

    queue<pii> q0;
    for (int i = 0; i < n; ++i) {
        cin >> rea[i];
        for (int j = 0; j < m; ++j) {
            danger[i][j] = INF;
            if (rea[i][j] == 'Z') {
                q0.push(pii(i, j));
                danger[i][j] = 1;
            }
        }
    }

    while (!q0.empty()) {
        int x = q0.front().first;
        int y = q0.front().second;
        q0.pop();
        for (int dx = -1; dx <= 1; ++dx)
            for (int dy = -1; dy <= 1; ++dy) {
                if (abs(dx) + abs(dy) != 1) continue;
                int nx = x + dx, ny = y + dy;
                if (valid(nx, ny) && danger[nx][ny] == INF && sci[nx][ny] != 'Y') {
                    danger[nx][ny] = danger[x][y] + 1;
                    q0.push(pii(nx, ny));
                }
            }
    }

    src = 0;
    sink = n * n + n * n + 1;
    int nodes = n * n * 2 + 2;
    headEdge.assign(nodes, -1);
    toNode.clear();
    nextEdge.clear();
    edgeCap.clear();
    distLevel.assign(nodes, -1);
    current.assign(nodes, -1);

    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < m; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                addEdge(src, idCell(x, y), sci[x][y] - '0');
            if (rea[x][y] >= '1' && rea[x][y] <= '9')
                addEdge(n * n + idCell(x, y), sink, rea[x][y] - '0');

            for (int X = 0; X < n; ++X) {
                for (int Y = 0; Y < m; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' || rea[X][Y] == 'Y' || rea[X][Y] == 'Z')
                        continue;

                    bool seen[101][101] = {};
                    queue<ppi> q1;
                    q1.push(ppi(pii(x, y), 1));
                    seen[x][y] = true;
                    while (!q1.empty()) {
                        int cx = q1.front().first.first;
                        int cy = q1.front().first.second;
                        int tim = q1.front().second;
                        q1.pop();
                        if (cx == X && cy == Y) {
                            seen[X][Y] = true;
                            break;
                        }
                        if (tim >= danger[cx][cy] || tim >= deadline) continue;
                        for (int dx = -1; dx <= 1; ++dx) {
                            for (int dy = -1; dy <= 1; ++dy) {
                                if (abs(dx) + abs(dy) != 1) continue;
                                int nx = cx + dx, ny = cy + dy;
                                if (valid(nx, ny) && !seen[nx][ny] &&
                                    sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' &&
                                    tim + 1 <= danger[nx][ny]) {
                                    seen[nx][ny] = true;
                                    q1.push(ppi(pii(nx, ny), tim + 1));
                                }
                            }
                        }
                    }
                    if (seen[X][Y])
                        addEdge(idCell(x, y), n * n + idCell(X, Y), INF);
                }
            }
        }
    }

    cout << maxflow() << endl;
    return 0;
}
